const { createReadStream } = require("node:fs");
const { createInterface } = require("node:readline");

const entree = createReadStream("./journal.log", { encoding: "utf8" });
const lignes = createInterface({ input: entree, crlfDelay: Infinity });
let total = 0;

lignes.on("line", (ligne) => {
  if (ligne.includes("ERROR")) total += 1;
});
lignes.on("close", () => console.log(String(total) + " erreur(s)"));

const { createReadStream, createWriteStream } = require("node:fs");

createReadStream("./source.txt")
  .pipe(createWriteStream("./copie.txt"))
  .on("finish", () => console.log("Copie terminée"));
